
#nullable enable

namespace tryAGI.OpenAI
{
    /// <summary>
    /// The quality of the image generated by the image generation tool call. One of `low`, `medium`, `high`, `xhigh`, `max`, or `auto`.
    /// </summary>
    public enum ImageGenToolCallQuality
    {
        /// <summary>
        ///
        /// </summary>
        Auto,
        /// <summary>
        ///
        /// </summary>
        High,
        /// <summary>
        ///
        /// </summary>
        Low,
        /// <summary>
        ///
        /// </summary>
        Max,
        /// <summary>
        ///
        /// </summary>
        Medium,
        /// <summary>
        ///
        /// </summary>
        Xhigh,
    }

    /// <summary>
    /// Enum extensions to do fast conversions without the reflection.
    /// </summary>
    public static class ImageGenToolCallQualityExtensions
    {
        /// <summary>
        /// Converts an enum to a string.
        /// </summary>
        public static string ToValueString(this ImageGenToolCallQuality value)
        {
            return value switch
            {
                ImageGenToolCallQuality.Auto => "auto",
                ImageGenToolCallQuality.High => "high",
                ImageGenToolCallQuality.Low => "low",
                ImageGenToolCallQuality.Max => "max",
                ImageGenToolCallQuality.Medium => "medium",
                ImageGenToolCallQuality.Xhigh => "xhigh",
                _ => throw new global::System.ArgumentOutOfRangeException(nameof(value), value, null),
            };
        }
        /// <summary>
        /// Converts an string to a enum.
        /// </summary>
        public static ImageGenToolCallQuality? ToEnum(string value)
        {
            return value switch
            {
                "auto" => ImageGenToolCallQuality.Auto,
                "high" => ImageGenToolCallQuality.High,
                "low" => ImageGenToolCallQuality.Low,
                "max" => ImageGenToolCallQuality.Max,
                "medium" => ImageGenToolCallQuality.Medium,
                "xhigh" => ImageGenToolCallQuality.Xhigh,
                _ => null,
            };
        }
    }
}